#include <bits/stdc++.h>
using namespace std;

struct Fenwick {
    int n;
    vector<long long> bit;

    Fenwick(int n) : n(n), bit(n + 1, 0) {}

    void add(int i, long long value) {
        for (; i <= n; i += i & -i) bit[i] += value;
    }

    long long sum(int i) const {
        long long result = 0;
        for (; i > 0; i -= i & -i) result += bit[i];
        return result;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    Fenwick slope(N), intercept(N);

    auto rangeAdd = [&](int l, int r, long long a, long long b) {
        slope.add(l, a);
        intercept.add(l, b);
        if (r < N) {
            slope.add(r + 1, -a);
            intercept.add(r + 1, -b);
        }
    };

    while (M--) {
        int type, i;
        cin >> type >> i;

        if (type == 1 || type == 2) {
            long long V;
            cin >> V;

            if (type == 1) {
                int r = min<long long>(N, i + V - 1);
                rangeAdd(i, r, -1, V + i);
            } else {
                int l = max<long long>(1, i - V + 1);
                rangeAdd(l, i, 1, V - i);
            }
        } else {
            long long a = slope.sum(i);
            long long b = intercept.sum(i);
            cout << a * i + b << '\n';
        }
    }

    return 0;
}
